package com.orqix.compiler;

/**
 * Validates canonical workflow definitions and compiles them to Flowable BPMN/DMN artifacts.
 * Rules and output format: docs/build/S4-workflow-compiler.md. Implementations are pure and thread-safe.
 */
public interface WorkflowCompiler {

    /** Semantic version of the generated output; bumped whenever generated bytes change (S4 section 9). */
    String version();

    /** Runs pipeline stages 1-7. Never throws for invalid input; problems are returned as issues. */
    ValidationReport validate(String definitionJson, CompileContext context);

    /**
     * Runs stages 1-8. Warnings are returned on the result; the caller decides whether they were acknowledged.
     *
     * @throws CompilationException when the definition has at least one blocker
     */
    CompiledWorkflow compile(String definitionJson, CompileContext context) throws CompilationException;
}
